from typing import Dict, List, Any, Optional, Tuple
import json

def simulate(initial_state: dict, events: list[dict]) -> dict:
    # Initialize the state
    capacities = initial_state.get("capacities", {"seats": 0, "laptops": 0, "projectors": 0})
    available = {resource: capacity for resource, capacity in capacities.items()}
    reservations = []
    waitlist = []

    # Track existing reservation IDs and user IDs
    existing_reservation_ids = set()
    existing_user_ids = set()

    # Track event results and notifications
    event_results = []
    notifications = []

    # Process each event in order
    for event in events:
        event_id = event.get("event_id")
        op = event.get("op")

        # Check for duplicate event_id
        if event_id in [e["event_id"] for e in event_results]:
            # Check if the event body is the same
            for result in event_results:
                if result["event_id"] == event_id and result["code"] == "invalid_event":
                    continue
                if result["event_id"] == event_id and result["code"] != "invalid_event":
                    # Event ID conflict
                    event_results.append({
                        "event_id": event_id,
                        "code": "event_id_conflict",
                        "replayed": False,
                        "admitted": []
                    })
                    continue
            # If the event is a duplicate, it's a replay
            event_results.append({
                "event_id": event_id,
                "code": "replayed",
                "replayed": True,
                "admitted": []
            })
            continue

        # Check if the event is valid
        if op == "reserve":
            if not all(k in event for k in ["reservation_id", "user_id", "needs", "priority"]):
                event_results.append({
                    "event_id": event_id,
                    "code": "invalid_event",
                    "replayed": False,
                    "admitted": []
                })
                continue
            reservation_id = event["reservation_id"]
            user_id = event["user_id"]
            needs = event["needs"]
            priority = event["priority"]

            # Validate needs
            if not all(k in needs for k in ["seats", "laptops", "projectors"]):
                event_results.append({
                    "event_id": event_id,
                    "code": "invalid_event",
                    "replayed": False,
                    "admitted": []
                })
                continue
            if any(value < 1 for value in needs.values()):
                event_results.append({
                    "event_id": event_id,
                    "code": "invalid_event",
                    "replayed": False,
                    "admitted": []
                })
                continue

            # Check for duplicate reservation ID or user ID
            if reservation_id in existing_reservation_ids:
                event_results.append({
                    "event_id": event_id,
                    "code": "duplicate_reservation",
                    "replayed": False,
                    "admitted": []
                })
                continue
            if user_id in existing_user_ids:
                event_results.append({
                    "event_id": event_id,
                    "code": "duplicate_user",
                    "replayed": False,
                    "admitted": []
                })
                continue

            # Check if all needed resources are available
            for resource, required in needs.items():
                if available[resource] < required:
                    event_results.append({
                        "event_id": event_id,
                        "code": "insufficient_capacity",
                        "replayed": False,
                        "admitted": []
                    })
                    continue

            # Add to waitlist
            waitlist.append(reservation_id)
            existing_reservation_ids.add(reservation_id)
            existing_user_ids.add(user_id)

            # Sort waitlist by priority and order
            waitlist.sort(key=lambda x: (priority, 0))

            # Check if any reservation in waitlist can be confirmed
            confirmed = []
            for res_id in waitlist:
                # Find the reservation
                for res in reservations:
                    if res["reservation_id"] == res_id:
                        break
                else:
                    continue

                # Check if all needed resources are available
                for resource, required in needs.items():
                    if available[resource] < required:
                        continue
                else:
                    # Confirm the reservation
                    confirmed.append(res_id)
                    for res in reservations:
                        if res["reservation_id"] == res_id:
                            res["status"] = "confirmed"
                            res["order"] = len(reservations) + 1
                            break
                    for resource, required in needs.items():
                        available[resource] -= required
                    # Add to notifications
                    notifications.append({
                        "event_id": event_id,
                        "type": "confirmed",
                        "reservation_id": res_id
                    })

            # Add event result
            event_results.append({
                "event_id": event_id,
                "code": "queued",
                "replayed": False,
                "admitted": confirmed
            })

        elif op == "cancel":
            if not all(k in event for k in ["reservation_id"]):
                event_results.append({
                    "event_id": event_id,
                    "code": "invalid_event",
                    "replayed": False,
                    "admitted": []
                })
                continue
            reservation_id = event["reservation_id"]

            # Check if reservation exists
            found = False
            for res in reservations:
                if res["reservation_id"] == reservation_id:
                    found = True
                    break

            if not found:
                event_results.append({
                    "event_id": event_id,
                    "code": "unknown_reservation",
                    "replayed": False,
                    "admitted": []
                })
                continue

            # Check if reservation is active
            if res["status"] == "cancelled":
                event_results.append({
                    "event_id": event_id,
                    "code": "not_active",
                    "replayed": False,
                    "admitted": []
                })
                continue

            # Cancel the reservation
            res["status"] = "cancelled"
            for resource, required in res["needs"].items():
                available[resource] += required

            # Add to notifications
            notifications.append({
                "event_id": event_id,
                "type": "cancelled",
                "reservation_id": reservation_id
            })

            # Add event result
            event_results.append({
                "event_id": event_id,
                "code": "cancelled",
                "replayed": False,
                "admitted": []
            })

        elif op == "amend":
            if not all(k in event for k in ["reservation_id", "needs", "priority"]):
                event_results.append({
                    "event_id": event_id,
                    "code": "invalid_event",
                    "replayed": False,
                    "admitted": []
                })
                continue
            reservation_id = event["reservation_id"]
            needs = event["needs"]
            priority = event["priority"]

            # Check if reservation exists
            found = False
            for res in reservations:
                if res["reservation_id"] == reservation_id:
                    found = True
                    break

            if not found:
                event_results.append({
                    "event_id": event_id,
                    "code": "unknown_reservation",
                    "replayed": False,
                    "admitted": []
                })
                continue

            # Check if reservation is active
            if res["status"] == "cancelled":
                event_results.append({
                    "event_id": event_id,
                    "code": "not_active",
                    "replayed": False,
                    "admitted": []
                })
                continue

            # Check if needs are valid
            if not all(k in needs for k in ["seats", "laptops", "projectors"]):
                event_results.append({
                    "event_id": event_id,
                    "code": "invalid_event",
                    "replayed": False,
                    "admitted": []
                })
                continue
            if any(value < 1 for value in needs.values()):
                event_results.append({
                    "event_id": event_id,
                    "code": "invalid_event",
                    "replayed": False,
                    "admitted": []
                })
                continue

            # Check if the new needs can be met
            for resource, required in needs.items():
                if available[resource] < required:
                    event_results.append({
                        "event_id": event_id,
                        "code": "insufficient_capacity",
                        "replayed": False,
                        "admitted": []
                    })
                    continue

            # Update the reservation
            res["needs"] = needs
            res["priority"] = priority

            # Add to notifications
            notifications.append({
                "event_id": event_id,
                "type": "amended",
                "reservation_id": reservation_id
            })

            # Add event result
            event_results.append({
                "event_id": event_id,
                "code": "amended",
                "replayed": False,
                "admitted": []
            })

        elif op == "set_capacity":
            if not all(k in event for k in ["resource", "capacity"]):
                event_results.append({
                    "event_id": event_id,
                    "code": "invalid_event",
                    "replayed": False,
                    "admitted": []
                })
                continue
            resource = event["resource"]
            capacity = event["capacity"]

            # Check if resource is valid
            if resource not in capacities:
                event_results.append({
                    "event_id": event_id,
                    "code": "invalid_event",
                    "replayed": False,
                    "admitted": []
                })
                continue

            # Check if capacity is valid
            if capacity < 0:
                event_results.append({
                    "event_id": event_id,
                    "code": "invalid_event",
                    "replayed": False,
                    "admitted": []
                })
                continue

            # Check if capacity is below usage
            if capacity < sum(res["needs"].get(resource, 0) for res in reservations if res["status"] == "confirmed"):
                event_results.append({
                    "event_id": event_id,
                    "code": "capacity_below_usage",
                    "replayed": False,
                    "admitted": []
                })
                continue

            # Update capacity and available
            capacities[resource] = capacity
            available[resource] = capacity

            # Add to notifications
            notifications.append({
                "event_id": event_id,
                "type": "capacity_updated",
                "reservation_id": ""
            })

            # Add event result
            event_results.append({
                "event_id": event_id,
                "code": "capacity_updated",
                "replayed": False,
                "admitted": []
            })

        # Add event result for all cases
        event_results.append({
            "event_id": event_id,
            "code": "confirmed",
            "replayed": False,
            "admitted": []
        })

    # Sort reservations by reservation_id
    reservations.sort(key=lambda x: x["reservation_id"])

    # Sort waitlist by priority and order
    waitlist.sort(key=lambda x: (priority, 0))

    # Build the final state
    final_state = {
        "capacities": capacities,
        "available": available,
        "reservations": reservations,
        "waitlist": waitlist
    }

    return {
        "event_results": event_results,
        "final_state": final_state,
        "notifications": notifications
    }
